// mergeCompanies.js — pure-JS DETERMINISTIC non-clobber merge for COMPANY records.
//
// Companies sibling of mergeContacts.js. Same deterministic gate + provenance-blob shape
// (src/merge_policy.py), different field policy and two rules contacts do not have:
//   - `domain` hard guard (mirrors the contacts `email` guard)
//   - evidence-URL requirement on the ICP fields (field_policy.yaml
//     lv_produces_content.require_evidence_url / lv_org_type.require_evidence_url_for)
//
// PROVENANCE MODEL (Phase 15): per-field metadata/staging is ONE provenance object keyed
// by field ({source, confidence, verified_at, evidence_url?, validation_status, value}),
// not flat `{field}_source`/`{provider}_{field}` properties. The caller (the
// build_cloud_workflows.py wrapper) serializes it ONCE via stableStringify() into
// `lv_enrichment_provenance`, alongside the 2 cache-key datetimes this module surfaces on
// `cacheKeys` for lv_org_type / lv_produces_content.
//
// NO Haiku / NO Sonnet — the LLM stages merge_policy runs after the gate are omitted
// (n8n Code nodes cannot call them; escalation happens downstream). The decision IS the
// gate's decision.
//
// This computes the POLICY decision only. Whether a promoted field actually ships to
// HubSpot is the write gate's call (ALLOW_CANONICAL_WRITES, CLAUDE.md §18.5/§29) — that
// is deliberately NOT duplicated here.


// Default companies field policy (source of truth: config/field_policy.yaml `companies`).
// lv_org_type's gated set is NOT hand-typed here (spec TX-4) — it derives from
// config/taxonomy.yaml org_types.*.requires_evidence via the generated taxonomy module,
// so adding/removing an evidence-gated org_type is a taxonomy.yaml + rebuild, not a
// second hand edit here.
const DEFAULT_COMPANY_POLICY = {
  domain:                  { class: "manual_protected",  min_confidence: 95 },
  industry:                { class: "stale_refreshable", min_confidence: 75 },
  numberofemployees:       { class: "stale_refreshable", min_confidence: 70 },
  annualrevenue:           { class: "review_required",   min_confidence: 85 },
  lv_revenue_band:         { class: "system_owned",      min_confidence: 75 },
  lv_employee_band:        { class: "system_owned",      min_confidence: 70 },
  // 75: deliberately above the flat-firmographic band (lv_employee_band at 70) because
  // this field is the geography input to the non-ANZ hard veto, so a wrong promotion
  // disqualifies a real account -- and below the evidence-gated judgment fields (85)
  // because it is a normalized enum with no evidence-URL requirement, so demanding
  // provider certainty here would leave it effectively stage-only and defeat the
  // purpose. This threshold is a reviewable judgment, not a derived constant.
  lv_country_region_normalized: { class: "system_owned", min_confidence: 75 },
  lv_org_type:             { class: "system_owned",      min_confidence: 80,
                             require_evidence_url_for: EVIDENCE_GATED_ORG_TYPES },
  lv_produces_content:     { class: "system_owned",      min_confidence: 85,
                             require_evidence_url: true },
  lv_content_type:         { class: "system_owned",      min_confidence: 75 },
  lv_sponsorship_reliant:  { class: "system_owned",      min_confidence: 70 },
  lv_is_hardware_vendor:   { class: "system_owned",      min_confidence: 85 },
  lv_is_gambling_operator: { class: "system_owned",      min_confidence: 85 },
  // lv_icp_fit_score / lv_icp_tier: Approach C (Phase 15 criterion 4) — HubSpot owns
  // these derived outputs. Removed from policy so either falls to the default
  // non-promoting policy (fill_blank_only) if it ever appears in a candidate, never
  // "score_output".
  lv_anti_icp_flag:        { class: "veto_output",       min_confidence: 0 },
  lv_anti_icp_reason:      { class: "veto_output",       min_confidence: 0 },
};

function _isBlank(v) {
  return v === null || v === undefined || v === "" ||
         (Array.isArray(v) && v.length === 0);
}

function _nowIso() {
  return new Date().toISOString();
}

// Recursively sort object keys before JSON.stringify — the JS half of the shared
// byte-identical serialization contract with src/merge_policy.py's serialize_provenance()
// (Python: json.dumps(obj, sort_keys=True, separators=(",", ":"), ensure_ascii=False)).
// JSON.stringify already emits compact ("," / ":") separators and raw (non-escaped)
// UTF-8 by default, matching Python's ensure_ascii=False — the only remaining gap is key
// ORDER, which this closes.
function _sortedForStringify(value) {
  if (Array.isArray(value)) return value.map(_sortedForStringify);
  if (value !== null && typeof value === "object") {
    const out = {};
    for (const k of Object.keys(value).sort()) out[k] = _sortedForStringify(value[k]);
    return out;
  }
  return value;
}

function stableStringify(value) {
  return JSON.stringify(_sortedForStringify(value));
}

// The 2 company cache-key fields (RT-5/SJ-2's queryable datetimes) — everything else
// rides in the provenance blob.
const COMPANY_CACHE_KEY_FIELDS = {
  lv_org_type: "lv_org_type_verified_at",
  lv_produces_content: "lv_produces_content_verified_at",
};

// Does this field+value need an evidence URL before it may promote?
// require_evidence_url: always. require_evidence_url_for: only for the listed values
// (e.g. lv_org_type may promote to "other" unevidenced, but not to "hardware_vendor").
function _needsEvidence(policy, value) {
  if (!policy) return false;
  if (policy.require_evidence_url === true) return true;
  const gated = policy.require_evidence_url_for;
  if (Array.isArray(gated)) return gated.indexOf(value) !== -1;
  return false;
}

// Deterministic gate — single candidate, mirrors merge_policy.deterministic_gate.
// has_conflict is always false with one candidate, so the conflict branch is dropped.
function _gate(field, currentValue, confidence, policy, evidenceUrl, value) {
  const fieldClass = (policy && policy.class) || "fill_blank_only";
  const minConfidence = (policy && policy.min_confidence != null) ? policy.min_confidence : 80;

  if (confidence < minConfidence) {
    return { decision: "needs_review",
             reason: `Best confidence ${confidence} below threshold ${minConfidence}.` };
  }
  // Evidence gate runs BEFORE the class branches: an unevidenced ICP claim is never
  // promotable no matter how system_owned the field is (CLAUDE.md §21.3).
  if (_needsEvidence(policy, value) && _isBlank(evidenceUrl)) {
    return { decision: "needs_review",
             reason: `Field ${field}=${value} requires an evidence URL; none supplied.` };
  }
  if (fieldClass === "manual_protected") {
    return { decision: "stage_only", reason: "Field is manual_protected." };
  }
  if (fieldClass === "review_required") {
    return { decision: "needs_review", reason: "Field requires review." };
  }
  if (fieldClass === "system_owned" || fieldClass === "score_output" || fieldClass === "veto_output") {
    return { decision: "promote", reason: "System-owned field passed confidence threshold." };
  }
  if (fieldClass === "fill_blank_only") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "stage_only", reason: "Current value exists and field is fill_blank_only." };
  }
  if (fieldClass === "stale_refreshable") {
    if (_isBlank(currentValue)) {
      return { decision: "promote", reason: "Current value blank and candidate passed threshold." };
    }
    return { decision: "needs_review", reason: "Refresh candidate requires review in MVP." };
  }
  return { decision: "stage_only", reason: "Default conservative behavior." };
}

function _statusFor(decision) {
  // Deterministic (no LLM) validation_status from source_registry vocabulary.
  return decision === "needs_review" ? "human_review_required" : "provider_only";
}

// mergeCompanies(existingProps, candidateRow, fieldPolicy?, opts?)
//   existingProps: current HubSpot company properties (the record being enriched)
//   candidateRow:  canonical-keyed candidate values (post normalizeProviders + score)
//   fieldPolicy:   companies policy block; defaults to DEFAULT_COMPANY_POLICY
//   opts:          { source="provider", confidence=80, evidence={field: url},
//                    confidenceByField={field: number} }
//                  `evidence` mirrors enrichmentGate's opts.validity: an upstream-supplied
//                  per-field map, absent = no evidence.
//                  `confidenceByField` (Phase 15.5 TA-8, additive) — a per-field override
//                  of the flat `confidence`; when a field has an entry here it wins,
//                  otherwise the flat value (and its 80 default) applies exactly as
//                  before. Every current caller omits this key and is therefore
//                  byte-identical. READ D2 (docs/... §8.5 / RESEARCH.md) before ever
//                  wiring an A/R/G/T composite score in here: this map must only ever
//                  carry a 0-100 confidence on the SAME scale as `confidence`
//                  (the judge verdict's per-field confidence), never the composite.
function mergeCompanies(existingProps, candidateRow, fieldPolicy, opts) {
  existingProps = existingProps || {};
  candidateRow = candidateRow || {};
  const policy = fieldPolicy || DEFAULT_COMPANY_POLICY;
  const source = (opts && opts.source) || "provider";
  const flatConfidence = (opts && opts.confidence != null) ? opts.confidence : 80;
  const confidenceByField = (opts && opts.confidenceByField) || {};
  const evidence = (opts && opts.evidence) || {};
  const verifiedAt = _nowIso();

  const canonicalPatch = {};
  const provenance = {};
  const cacheKeys = {};
  const decisions = [];

  for (const field of Object.keys(candidateRow)) {
    const value = candidateRow[field];
    if (_isBlank(value)) continue; // nothing to merge

    const currentValue = existingProps[field];
    const fieldPol = policy[field] || { class: "fill_blank_only", min_confidence: 80 };
    const evidenceUrl = evidence[field];
    // The resolved per-field value is used EVERYWHERE the flat one used to be — the gate
    // threshold, the provenance entry, and the decision record — so the recorded
    // confidence and the confidence that made the decision can never disagree.
    const confidence = confidenceByField[field] != null ? confidenceByField[field] : flatConfidence;

    const gate = _gate(field, currentValue, confidence, fieldPol, evidenceUrl, value);
    let decision = gate.decision;

    // HARD GUARD: domain never promotes to canonical on the enrich path (belt-and-braces —
    // the manual_protected class + the 95 threshold already prevent it, but this holds
    // regardless of policy edits). Mirrors the mergeContacts email guard.
    if (field === "domain" && decision === "promote") decision = "stage_only";

    const validationStatus = _statusFor(decision);

    // ONE provenance entry per field — replaces the old flat metadataPatch/stagingPatch.
    const entry = { source, confidence, verified_at: verifiedAt,
                    validation_status: validationStatus, value };
    if (!_isBlank(evidenceUrl)) entry.evidence_url = evidenceUrl;
    provenance[field] = entry;

    if (decision === "promote") {
      canonicalPatch[field] = value;
      // STALE-TIMESTAMP FIX (Phase 16.3, companies twin of Phase 16.2 gpt #6): the
      // cache-key datetime is stamped ONLY when the field is actually ACCEPTED — moved
      // inside this branch (was previously unconditional) so a needs_review/stale-but-
      // unpromoted candidate is never marked fresh, which would otherwise suppress the
      // next stale-refresh check (CLAUDE.md §19.5) forever.
      if (COMPANY_CACHE_KEY_FIELDS[field]) {
        cacheKeys[COMPANY_CACHE_KEY_FIELDS[field]] = verifiedAt;
      }
    }

    decisions.push({
      field,
      current_value: currentValue === undefined ? null : currentValue,
      chosen_value: value,
      source_provider: source,
      decision,
      confidence,
      reason: gate.reason,
      validation_status: validationStatus,
      evidence_url: _isBlank(evidenceUrl) ? null : evidenceUrl,
      verified_at: verifiedAt,
    });
  }

  return { canonicalPatch, provenance, cacheKeys, decisions };
}

// reviewApply.js — pure-JS §22.2 review-loop apply function for n8n Code nodes.
//
// CONSUMER CONTRACT: consumes EXACTLY what ENRICH_DECIDE_CO_CLOUD (build_cloud_workflows.py)
// writes into lv_enrichment_review_candidate_json — stableStringify(needsReview), where
// needsReview is mergeCompanies()'s decisions[] filtered to decision === "needs_review".
// Each decision is shaped { field, current_value, chosen_value, source_provider, decision,
// confidence, reason, validation_status, evidence_url, verified_at } (mergeCompanies.js:213-224).
//
// reviewApply(candidateJson, refetchedProperties) -> { canonicalPatch, clearPatch, stale, reason }
//
// STRUCTURAL Approach-C guard: canonicalPatch only ever accepts a field that is a key of
// mergeCompanies' own DEFAULT_COMPANY_POLICY — the same allowlist mergeCompanies itself
// promotes from. The two HubSpot-derived ICP score/tier outputs (Approach C) are
// deliberately ABSENT from that policy object (see mergeCompanies.js's own comment), so a
// candidate JSON that illegitimately names one is silently dropped without this file ever
// naming either field literally.
//
// FAIL-CLOSED: malformed / truncated JSON never throws -> empty patches + a reason.
// NON-CLOBBER (compare-and-set): a held decision's `current_value` is compared against the
// freshly-refetched live value of that field. If ANY field disagrees, a newer manual edit
// landed after the candidate was created — apply NOTHING (both patches stay empty), report
// stale=true, and leave the record queued (do not clear its review flags). All-or-nothing
// avoids a partial-apply/re-check loop: applying only the non-conflicting fields this run
// would change their live values without clearing lv_enrichment_review_candidate_json, so
// the NEXT run's compare-and-set would see its own just-applied write as a "conflict".


function reviewApply(candidateJson, refetchedProperties) {
  refetchedProperties = refetchedProperties || {};

  let decisions;
  try {
    decisions = JSON.parse(candidateJson);
    if (!Array.isArray(decisions)) throw new Error("candidate JSON is not an array");
  } catch (e) {
    return { canonicalPatch: {}, clearPatch: {}, stale: false,
             reason: "malformed review candidate JSON" };
  }

  const allowedFields = Object.keys(DEFAULT_COMPANY_POLICY);
  const canonicalPatch = {};
  const staleFields = [];

  for (const d of decisions) {
    if (!d || typeof d.field !== "string" || allowedFields.indexOf(d.field) === -1) continue;
    const liveValue = refetchedProperties[d.field];
    const normalizedLive = liveValue === undefined ? null : liveValue;
    const storedCurrent = d.current_value === undefined ? null : d.current_value;
    if (JSON.stringify(normalizedLive) !== JSON.stringify(storedCurrent)) {
      staleFields.push(d.field);
      continue;
    }
    canonicalPatch[d.field] = d.chosen_value;
  }

  if (staleFields.length > 0) {
    return {
      canonicalPatch: {}, clearPatch: {}, stale: true,
      reason: `field(s) changed since candidate was created, re-review required: ${staleFields.join(",")}`,
    };
  }

  const clearPatch = {
    lv_enrichment_needs_review: false,
    lv_enrichment_review_approved: false,
    lv_enrichment_review_reason: "",
    lv_enrichment_review_candidate_json: "",
    lv_enrichment_reviewed_at: new Date().toISOString(),
  };

  return { canonicalPatch, clearPatch, stale: false, reason: "applied" };
}

// reviewDecision.js — pure-JS decision-to-property-patch for the SYNCHRONOUS
// `hubspot/review/decision` endpoint (Phase 30 Plan 02, D-08e).
//
// Sibling of reviewApply.js, not a replacement for it. reviewApply is the 15-minute
// backstop loop's compare-and-set APPLY engine (approve -> promote the held candidate ->
// clear the flags); this module serves the operator-driven endpoint. 30-03 routes the
// approve branch INTO reviewApply rather than re-implementing it (D-08d/D-15).
//
// CONSUMER CONTRACT: `Build Review Decision` (scripts/build_cloud_workflows.py) calls
//
//   buildReviewDecision({ decision, reason, reviewedBy, row, nowIso })
//     -> { properties, outcome, message }
//
// where `row` is the freshly-refetched HubSpot record already flattened by
// `Review Extract Record` ({ ...record.properties, hs_object_id, record_found }), and
// `properties` is put straight onto the row for the shared credential-bound PATCH node.
// `outcome` is one of: rejected | not_flagged | unsupported | refused.
//
// `reviewedBy` and `nowIso` are accepted but deliberately UNUSED on every branch this
// plan owns — they belong to 30-03's approve path, which stamps lv_enrichment_reviewed_by
// / lv_enrichment_reviewed_at as the human-provenance record. A rejection stamps neither,
// on purpose (below).
//
// D-10 / REVIEW-05 — THE LOAD-BEARING RULE: a rejection RECORDS THE REASON AND NOTHING
// ELSE. It never clears lv_enrichment_needs_review or lv_icp_needs_review, never blanks
// lv_enrichment_review_candidate_json, and never stamps a reviewed-at. The record stays in
// the queue WITH a recorded decision. "Clear the flag for consistency" is precisely the
// silent de-queueing REVIEW-05 forbids, so the rejection branch is kept literally minimal:
// build the one-key patch and return.
//
// FAIL-CLOSED: never throws, never does I/O, requires nothing outside n8n/code/. Anything
// unrecognised is `refused` with EMPTY properties — the endpoint's only writing outcome is
// `rejected`.

// The `lv_`-prefixed review family (config/hubspot_properties.yaml). The generic
// unprefixed names in the root CLAUDE.md do not exist in this deployment (30 D-08c).
const P_NEEDS_REVIEW = "lv_enrichment_needs_review";
const P_ICP_NEEDS_REVIEW = "lv_icp_needs_review";
const P_REVIEW_REASON = "lv_enrichment_review_reason";
const P_CANDIDATE_JSON = "lv_enrichment_review_candidate_json";
// Named for the same reason the two flags above are: so the D-10 guarantee reads as an
// explicit non-write of a known property rather than an accidental omission. 30-03's
// approve branch is what writes these two.
const P_REVIEWED_BY = "lv_enrichment_reviewed_by";  // eslint-disable-line no-unused-vars
const P_REVIEWED_AT = "lv_enrichment_reviewed_at";  // eslint-disable-line no-unused-vars

// HubSpot's own textarea ceiling — the same [:60000] cap merge_policy.py and the
// enrichment wrapper apply to every JSON blob they stage.
const MAX_TEXT = 60000;

// HubSpot returns booleancheckbox values as the STRINGS "true"/"false", so a bare
// truthiness test would read "false" as flagged.
function _truthy(v) {
  if (v === true) return true;
  if (typeof v === "string") return v.trim().toLowerCase() === "true";
  return false;
}

function buildReviewDecision(input) {
  const inp = (input && typeof input === "object") ? input : {};
  const refused = (message) => ({ properties: {}, outcome: "refused", message });

  const row = inp.row;
  if (!row || typeof row !== "object" || Array.isArray(row)) {
    return refused("no record to decide on");
  }
  if (row.record_found === false || row.hs_object_id === undefined
      || row.hs_object_id === null || row.hs_object_id === "") {
    return refused("record not found");
  }

  // D-09: a decision without a reason is still a decision, so absent reads as empty. A
  // reason of the WRONG TYPE is a malformed request, not an empty one.
  let reason = inp.reason;
  if (reason === undefined || reason === null) reason = "";
  if (typeof reason !== "string") return refused("reason must be text");
  if (reason.length > MAX_TEXT) reason = reason.slice(0, MAX_TEXT);

  if (inp.decision === "approve") {
    return {
      properties: {}, outcome: "unsupported",
      message: "approve is not served by this endpoint yet — use the review-approved "
             + "backstop loop, or wait for the approve path (Phase 30 Plan 03)",
    };
  }
  if (inp.decision !== "reject") {
    return refused("unknown decision " + JSON.stringify(inp.decision)
                   + ' — expected "approve" or "reject"');
  }

  // Flagged the way the queue itself defines flagged: either review flag set, or a held
  // candidate. "[]" is reviewApply's own empty default, so it is not a candidate.
  const rawCandidate = row[P_CANDIDATE_JSON];
  const candidate = (rawCandidate === undefined || rawCandidate === null)
    ? "" : String(rawCandidate).trim();
  const flagged = _truthy(row[P_NEEDS_REVIEW]) || _truthy(row[P_ICP_NEEDS_REVIEW])
                  || (candidate !== "" && candidate !== "[]");
  if (!flagged) {
    return {
      properties: {}, outcome: "not_flagged",
      message: "record is not in the review queue — nothing to decide",
    };
  }

  return {
    properties: { [P_REVIEW_REASON]: reason },
    outcome: "rejected",
    message: "rejection reason recorded; the record stays in the review queue",
  };
}

// --- n8n wrapper: Build Review Decision ---
const parsed = $('Parse Review Decision').first().json;
const first = $input.first();
const row = (first && first.json) || {};

let result;
if (parsed.object_type !== "companies") {
  // Companies only in this plan; contacts routing lands in 30-03. The fetch above already
  // ran against companies, which is a harmless read — no write can follow a refusal.
  result = { properties: {}, outcome: "refused",
             message: "only company records are served by this endpoint yet" };
} else {
  result = buildReviewDecision({
    decision: parsed.decision,
    reason: parsed.reason,
    reviewedBy: parsed.reviewed_by,
    row,
    nowIso: new Date().toISOString(),
  });
}

const properties = result.properties || {};
const hasWrite = Object.keys(properties).length > 0;

// BUG 12/21/25 row-carry family: SPREAD the refetched row rather than constructing a
// fresh object. `domain` lives on it and the write gate reads it for the allowlist check
// — a gate reading a field its lane does not emit has already cost this repo two armed
// windows. `properties`/`hs_object_id` are assigned after the spread so they still win.
//
// `dry_run` here is the ROUTING boolean `Review IF Dry Run` switches on, not an echo of
// the request: it is the caller's dry_run OR "there is no write to perform". A refused /
// not_flagged / unsupported outcome therefore reaches the response WITHOUT touching the
// write gate, the PATCH, or the verify refetch — so its verified_properties is null.
return [{ json: { ...row,
  hs_object_id: row.hs_object_id,
  properties,
  would_write: { ...properties },
  outcome: result.outcome,
  message: result.message,
  dry_run: !(parsed.dry_run === false && hasWrite),
}}];

// Build Review Response — the SINGLE node that shapes the response body. BOTH branches
// route through it, so the client sees one contract regardless of path (D-19):
//
//   { outcome, message, would_write, verified_properties, verified }
//
// `verified_properties` holds the INDEPENDENTLY REFETCHED record's values for exactly the
// `would_write` keys, read from `Review Verify Fetch` — a second HubSpot search issued
// AFTER the PATCH, never the PATCH's own response body. HubSpot's PATCH echoes back the
// record it just accepted, so comparing a write against its own echo proves the request
// was well-formed and nothing else: precisely the "an accepted response is not evidence"
// failure Phase 28 D-14 exists to prevent.
//
// It is null on the dry-run branch and on every non-writing outcome, and `verified` is
// null wherever `verified_properties` is. A WRITTEN decision that arrives with
// `verified_properties` null is a FAILURE for the client to report, never a success to
// assume — which is why nothing here ever defaults `verified` to true. The client
// re-derives the comparison itself; `verified` is a convenience, never the authority.
const d = $('Build Review Decision').first().json;
const wouldWrite = d.would_write || {};

let verified_properties = null;
let verified = null;

if (d.dry_run !== true) {
  const first = $input.first();
  const env = (first && first.json) || {};
  const rows = Array.isArray(env.results) ? env.results : (env.properties ? [env] : []);
  const props = rows.length ? (rows[0].properties || {}) : null;
  if (props) {
    verified_properties = {};
    for (const k of Object.keys(wouldWrite)) {
      verified_properties[k] = props[k] === undefined ? null : props[k];
    }
    // HubSpot stores and returns every property as a string, so compare stringwise: a
    // boolean or numeric intent must not read as a mismatch against its own stored form.
    verified = Object.keys(wouldWrite).every(
      (k) => String(verified_properties[k]) === String(wouldWrite[k]));
  }
}

return [{ json: {
  outcome: d.outcome,
  message: d.message,
  would_write: wouldWrite,
  verified_properties,
  verified,
}}];

const ALLOW_HUBSPOT_RECORD_WRITES = "false";
const ALLOW_HUBSPOT_CREATE = "false";
const ALLOW_HUBSPOT_REVIEW_WRITES = "false";
const TEST_RECORD_DOMAINS = "";
const TEST_RECORD_IDS = "";
function _writeSafetyAllows(action, hsObjectId, domain) {
  // Review writeback has its OWN authority (D-02): the review action never consults
  // ALLOW_HUBSPOT_RECORD_WRITES, and no other action consults ALLOW_HUBSPOT_REVIEW_WRITES,
  // so arming either gate grants nothing on the other path. The allowlist below is
  // shared and mandatory for both.
  if (action === "review") {
    if (String(ALLOW_HUBSPOT_REVIEW_WRITES).toLowerCase() !== "true") return false;
  } else {
    if (String(ALLOW_HUBSPOT_RECORD_WRITES).toLowerCase() !== "true") return false;
    if (action === "create" && String(ALLOW_HUBSPOT_CREATE).toLowerCase() !== "true") return false;
  }
  const allowedDomains = String(TEST_RECORD_DOMAINS).split(",").map((s) => s.trim().toLowerCase()).filter(Boolean);
  const allowedIds = String(TEST_RECORD_IDS).split(",").map((s) => s.trim()).filter(Boolean);
  if (!allowedDomains.length && !allowedIds.length) return false;  // empty allowlist denies everything
  if (hsObjectId && allowedIds.indexOf(String(hsObjectId)) !== -1) return true;
  if (domain && allowedDomains.indexOf(String(domain).toLowerCase()) !== -1) return true;
  return false;
}

// Drops any row the allowlist does not permit. An empty allowlist denies all.
return $input.all().filter((it) => _writeSafetyAllows(
  'review',
  it.json.hs_object_id || (it.json.existingRecord && it.json.existingRecord.hs_object_id) || null,
  (it.json.identity_keys && it.json.identity_keys.domain) || it.json.domain || null,
));
